const jwt = require('jsonwebtoken');

// ADVERTENCIA: JWT_SECRET debe estar definido en el archivo .env y NUNCA hardcodeado en el código fuente.

/**
 * Middleware de autenticación JWT.
 * Verifica el token Bearer del header Authorization y adjunta el payload a req.user.
 *
 * TODO: En la iteración con MongoDB, agregar verificación de token en lista negra (blacklist)
 * para soporte de logout antes de llamar a next().
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function authMiddleware(req, res, next) {
  // Paso 1 - Extracción del header
  const authorizationHeader = req.headers.authorization;

  if (!authorizationHeader) {
    return res.status(401).json({
      success: false,
      message: 'No se proporcionó token de autenticación.',
    });
  }

  // Paso 2 - Validación del esquema Bearer
  const parts = authorizationHeader.split(' ');

  if (parts.length !== 2 || parts[0] !== 'Bearer') {
    return res.status(401).json({
      success: false,
      message: 'Formato de token inválido. Se esperaba: Bearer <token>',
    });
  }

  // Paso 3 - Extracción del token
  const rawToken = parts[1];

  // Paso 4 - Verificación criptográfica
  try {
    // En producción se debe especificar algorithms: ['HS256'] explícitamente para evitar ataques de confusión de algoritmo.
    const decodedPayload = jwt.verify(rawToken, process.env.JWT_SECRET);

    // Paso 5 - Adjuntar payload al request (solo lectura para controladores downstream)
    req.user = decodedPayload;

    // Paso 6 - Llamada a next() solo tras verificación exitosa
    next();
  } catch (error) {
    // Paso 7 - Manejo de errores de jsonwebtoken

    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({
        success: false,
        message: 'El token ha expirado.',
        expiredAt: error.expiredAt,
      });
    }

    if (error.name === 'JsonWebTokenError') {
      // Nunca revelar si el secreto es incorrecto versus token malformado;
      // ambos casos responden con el mismo mensaje genérico para no dar información al atacante.
      return res.status(401).json({
        success: false,
        message: 'Token inválido.',
      });
    }

    // Error inesperado (ej: JWT_SECRET no definido u otro error interno)
    // En iteraciones futuras reemplazar console.error por el logger de winston.
    // NUNCA loguear el token JWT completo.
    console.error('[authMiddleware] Error inesperado durante la verificación del token:', error.message);

    return res.status(500).json({
      success: false,
      message: 'Error interno del servidor durante la autenticación.',
    });
  }
}

module.exports = authMiddleware;

const logger = require('../config/logger');

const classifyError = (err) => {
  if (err.name === 'ValidationError' || Array.isArray(err.errors)) {
    return 'VALIDATION_ERROR';
  }

  if (err.name === 'JsonWebTokenError') {
    return 'JWT_INVALID';
  }

  if (err.name === 'TokenExpiredError') {
    return 'JWT_EXPIRED';
  }

  if (err.name === 'NotBeforeError') {
    return 'JWT_NOT_BEFORE';
  }

  if (err instanceof SyntaxError && Object.prototype.hasOwnProperty.call(err, 'body')) {
    return 'MALFORMED_JSON';
  }

  const statusCode = err.statusCode || err.status;
  if (statusCode === 404) {
    return 'NOT_FOUND';
  }

  return 'INTERNAL_SERVER_ERROR';
};

const normalizeStatusCode = (err) => {
  const code = err.statusCode || err.status;
  if (typeof code === 'number' && code >= 400 && code <= 599) {
    return code;
  }
  return 500;
};

const errorHandler = (err, req, res, next) => {
  try {
    const statusCode = normalizeStatusCode(err);
    const errorType = classifyError(err);
    const isProduction = process.env.NODE_ENV === 'production';
    const isServerError = statusCode >= 500;

    let clientMessage;
    if (isProduction && isServerError) {
      clientMessage = 'Internal server error';
    } else {
      clientMessage = err.message || 'An unexpected error occurred';
    }

    let errorDetails;
    if (Array.isArray(err.errors) && err.errors.length > 0) {
      if (!(isProduction && isServerError)) {
        errorDetails = err.errors;
      }
    }

    const payload = {
      success: false,
      error: {
        type: errorType,
        message: clientMessage,
        ...(errorDetails !== undefined && { details: errorDetails }),
        code: err.code || undefined,
      },
      meta: {
        timestamp: new Date().toISOString(),
        path: req.originalUrl,
        method: req.method,
        ...(req.id !== undefined && { requestId: req.id }),
      },
    };

    if (payload.error.code === undefined) {
      delete payload.error.code;
    }

    const logMetadata = {
      statusCode,
      method: req.method,
      url: req.originalUrl,
      errorType,
      stack: err.stack,
      ...(req.id !== undefined && { requestId: req.id }),
      ...(req.user && req.user.id !== undefined && { userId: req.user.id }),
    };

    if (isServerError) {
      logger.error(err.message || 'Internal server error', logMetadata);
    } else {
      logger.warn(err.message || 'Client error', logMetadata);
    }

    if (res.headersSent) {
      return next(err);
    }

    return res.status(statusCode).json(payload);
  } catch (handlerError) {
    return next(err);
  }
};

module.exports = { errorHandler, classifyError };

const morgan = require('morgan');
const logger = require('../config/logger');

const morganStream = {
  write: (message) => {
    logger.http(message.trim());
  },
};

const environment = process.env.NODE_ENV || 'development';

const morganFormat = environment === 'production' ? 'combined' : 'dev';

const skipLogging = (req, res) => {
  return process.env.NODE_ENV === 'test';
};

module.exports = morgan(morganFormat, {
  stream: morganStream,
  skip: skipLogging,
});

const { validationResult } = require('express-validator');
const logger = require('../config/logger');

function validateInput(req, res, next) {
  const result = validationResult(req);

  if (result.isEmpty()) {
    return next();
  }

  const errors = result.array({ onlyFirstError: true });

  logger.warn('Validation failed', {
    method: req.method,
    path: req.path,
    ip: req.ip,
    errorCount: errors.length,
  });

  return res.status(422).json({
    status: 'error',
    code: 'VALIDATION_ERROR',
    message: 'Los datos de entrada no son válidos',
    errors: errors.map(({ path, msg, value }) => ({
      field: path,
      message: msg,
      value,
    })),
  });
}

module.exports = validateInput;

